func newSFNTagResourceCmd() *cobra.Command {
	var resourceArn string
	var tags []string

	cmd := &cobra.Command{
		Use:   "tag-resource",
		Short: "TagResource",
		RunE: func(cmd *cobra.Command, _ []string) error {
			cfg, err := newAWSConfig(cmd.Context())
			if err != nil {
				return err
			}

			client := sfn.NewFromConfig(cfg, func(o *sfn.Options) {
				o.BaseEndpoint = aws.String(endpointURL)
			})

			input := &sfn.TagResourceInput{}

			if resourceArn != "" {
				input.ResourceArn = aws.String(resourceArn)
			}

			for _, raw := range tags {
				var val types.Tag
				if err := cligen.SetFieldsFromKV(reflect.ValueOf(&val).Elem(), raw); err != nil {
					return fmt.Errorf("tag-resource: parse --tags: %w", err)
				}
				input.Tags = append(input.Tags, val)
			}

			_, err = client.TagResource(cmd.Context(), input)
			if err != nil {
				return fmt.Errorf("tag-resource failed: %w", err)
			}

			return nil
		},
	}

	cmd.Flags().StringVar(&resourceArn, "resource-arn", "", "Resource arn")

	cmd.Flags().StringArrayVar(&tags, "tags", nil, "Tags (key=value,key2=value2, repeatable)")

	cmd.Flags().String("region", "", "Region override (ignored)")

	return cmd
}

